import{_ as t,o,c as s,a2 as n}from"./chunks/framework.CfwCq2QB.js";const u=JSON.parse('{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/faq/index.md","filePath":"en/faq/index.md"}'),a={name:"en/faq/index.md"};function r(i,e,l,d,h,p){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to &quot;FAQ &amp; troubleshooting&quot;">​</a></h1><h2 id="the-selection-toolbar-doesn-t-appear" tabindex="-1">The selection toolbar doesn&#39;t appear? <a class="header-anchor" href="#the-selection-toolbar-doesn-t-appear" aria-label="Permalink to &quot;The selection toolbar doesn&#39;t appear?&quot;">​</a></h2><p><strong>Symptom</strong>: you select text on a page and no toolbar shows up.</p><p><strong>Cause</strong>: selection is off for that site, off globally, or you&#39;re in an input field where only writing actions show.</p><p><strong>Steps</strong>:</p><ol><li>Open the popup&#39;s Features page and check the &quot;Selection toolbar&quot; switch — &quot;Off on {host}&quot; means turn it back on</li><li>Check Settings → Selection → &quot;Enable selection&quot; for the global switch</li><li>Text selected inside an input shows only writing actions (Polish / Fix / Formal and input-scope custom actions) — no Translate / Explain there is normal</li><li>Still nothing? Refresh the page and select again; pages opened before the extension was installed need one refresh for the content script to attach</li></ol><h2 id="web-meetings-or-voice-calls-stopped-connecting-after-enabling-real-ip-protection" tabindex="-1">Web meetings or voice calls stopped connecting after enabling real IP protection? <a class="header-anchor" href="#web-meetings-or-voice-calls-stopped-connecting-after-enabling-real-ip-protection" aria-label="Permalink to &quot;Web meetings or voice calls stopped connecting after enabling real IP protection?&quot;">​</a></h2><p><strong>Symptom</strong>: with protection on (especially &quot;Hide real IP&quot;), web meetings and calls slow down or fail.</p><p><strong>Cause</strong>: a known cost of the protection — audio/video connections must go through the proxy, which shows most with UDP-less proxies. Meeting client apps are unaffected.</p><p><strong>Steps</strong>:</p><ol><li>Set the level back to &quot;Off (browser default)&quot; under Settings → Network → Real IP protection and refresh the page to confirm</li><li>If that&#39;s the cause, consider a lighter level like &quot;Hide LAN addresses&quot; instead (your real IP stays visible — your call)</li><li>Meetings on only a few sites? Temporarily switch to &quot;Off&quot; for the call, then back</li></ol><p>See <a href="/dev-go-docs/en/features/ip-protection.html">Real IP protection</a>.</p><h2 id="proxy-switching-doesn-t-work-in-firefox" tabindex="-1">Proxy switching doesn&#39;t work in Firefox? <a class="header-anchor" href="#proxy-switching-doesn-t-work-in-firefox" aria-label="Permalink to &quot;Proxy switching doesn&#39;t work in Firefox?&quot;">​</a></h2><p><strong>Symptom</strong>: switching network modes in the Firefox build does nothing.</p><p><strong>Cause</strong>: DevGo&#39;s proxy control uses Chromium&#39;s <code>chrome.proxy</code> settings API; Firefox implements it differently and isn&#39;t supported yet.</p><p><strong>Steps</strong>:</p><ol><li>On Firefox, use your system proxy or your proxy app&#39;s own routing</li><li>Real IP protection, CORS debugging, and other network features are unaffected</li><li>Firefox proxy support is on the roadmap — follow <a href="https://github.com/fedtop/DevGo/issues" target="_blank" rel="noreferrer">Issues</a></li></ol><h2 id="nothing-shows-up-in-page-tools-webmcp" tabindex="-1">Nothing shows up in page tools (WebMCP)? <a class="header-anchor" href="#nothing-shows-up-in-page-tools-webmcp" aria-label="Permalink to &quot;Nothing shows up in page tools (WebMCP)?&quot;">​</a></h2><p><strong>Symptom</strong>: the side panel&#39;s &quot;Page tools&quot; page says unsupported, unreadable, or no tools.</p><p><strong>Cause</strong>: WebMCP is an experimental Chrome 150+ feature that needs manual enabling — and the page itself must register tools via WebMCP.</p><p><strong>Steps</strong>:</p><ol><li>Confirm Chrome ≥ 150</li><li>Open <code>chrome://flags</code>, search &quot;WebMCP for testing&quot;, enable, restart the browser</li><li>Ordinary pages with no tools registered is normal; hit &quot;Check again&quot; when in doubt</li></ol><p>See <a href="/dev-go-docs/en/features/webmcp.html">Page tools (WebMCP)</a>. If the site has no WebMCP tools, you can add your own — see <a href="/dev-go-docs/en/features/site-tools.html">Site tools &amp; recording</a>; no experimental flag needed.</p><h2 id="a-site-tool-fails-with-element-not-found" tabindex="-1">A site tool fails with &quot;element not found&quot;? <a class="header-anchor" href="#a-site-tool-fails-with-element-not-found" aria-label="Permalink to &quot;A site tool fails with &quot;element not found&quot;?&quot;">​</a></h2><p><strong>Cause</strong>: the site changed, the element hasn&#39;t loaded yet, or the run didn&#39;t start on the page the tool expects.</p><p><strong>Fix</strong>:</p><ol><li>For recorded tools, turn on &quot;Open the starting URL first&quot; so every run starts from the same place</li><li>Ask the AI in chat to &quot;fix this tool&quot; — it re-inspects the page, test-runs, and saves over the old one</li><li>If the site changed a lot, record it again</li></ol><p>See <a href="/dev-go-docs/en/features/site-tools.html">Site tools &amp; recording</a>.</p><h2 id="ai-errors-401-404-429" tabindex="-1">AI errors: 401 / 404 / 429? <a class="header-anchor" href="#ai-errors-401-404-429" aria-label="Permalink to &quot;AI errors: 401 / 404 / 429?&quot;">​</a></h2><p><strong>Symptom</strong>: selection AI actions, the side panel assistant, or AI translation report errors.</p><p><strong>Cause and fix</strong> (by error):</p><table tabindex="0"><thead><tr><th>Error</th><th>Meaning</th><th>Fix</th></tr></thead><tbody><tr><td>Auth failed / 401</td><td>Invalid API key, or one that doesn&#39;t belong to this base URL&#39;s service</td><td>Check the key; if you just switched provider presets, make sure the key is from that service</td></tr><tr><td>404</td><td>Base URL or model not found</td><td>Base URL up to <code>/v1</code> (the rest is appended); check the model name against the provider&#39;s docs</td></tr><tr><td>429</td><td>Too many requests or quota exceeded</td><td>Retry later; check your account&#39;s quota and concurrency limits</td></tr><tr><td>Connection failed / timeout</td><td>Network unreachable or wrong address</td><td>Check your network (proxy needed?); use &quot;Test connection&quot;</td></tr></tbody></table><p>Configure under Settings → <a href="/dev-go-docs/en/settings/models.html">AI models</a>.</p><h2 id="page-translation-shows-no-translations" tabindex="-1">Page translation shows no translations? <a class="header-anchor" href="#page-translation-shows-no-translations" aria-label="Permalink to &quot;Page translation shows no translations?&quot;">​</a></h2><p><strong>Symptom</strong>: you clicked &quot;Translate this page&quot; and nothing changed — or some paragraphs have no translation.</p><p><strong>Steps</strong>:</p><ol><li>With the target language on &quot;Auto&quot;, Chinese pages translate to English and everything else to Simplified Chinese — translating into the same language looks like nothing happened; fix an explicit target language</li><li>Engine unreachable: Google needs a proxy; Microsoft doesn&#39;t. Switch engines in the popup</li><li>&quot;AI model&quot; engine without a config or with a dead key: the popup says &quot;No translation model configured yet&quot; — configure it or switch back to Microsoft</li><li>A few paragraphs failing: click ↻ after them to retry; switch engines if they keep failing</li><li>Browser built-in pages and the extension store can&#39;t be translated — expected</li></ol><h2 id="the-extension-got-disabled-after-an-update" tabindex="-1">The extension got disabled after an update? <a class="header-anchor" href="#the-extension-got-disabled-after-an-update" aria-label="Permalink to &quot;The extension got disabled after an update?&quot;">​</a></h2><p><strong>Symptom</strong>: after updating DevGo, the browser says the extension is disabled or needs re-confirmation.</p><p><strong>Cause</strong>: how browsers treat <strong>permission differences</strong> between versions. DevGo&#39;s <code>privacy</code> permission is optional and only requested when you enable real IP protection, so it never triggers this; if a future version adds regular permissions, the browser asks you to re-confirm by rule.</p><p><strong>Steps</strong>: re-enable DevGo on its card in <code>chrome://extensions</code> — settings and data are unaffected.</p><h2 id="how-do-i-reset-to-defaults" tabindex="-1">How do I reset to defaults? <a class="header-anchor" href="#how-do-i-reset-to-defaults" aria-label="Permalink to &quot;How do I reset to defaults?&quot;">​</a></h2><p><strong>Symptom</strong>: you want a factory-fresh DevGo.</p><p><strong>Steps</strong>:</p><ol><li>There&#39;s no one-click reset. Per feature, revert in the matching settings page (delete custom actions one by one, clear site lists, and so on)</li><li>For a clean slate: remove the extension and install again — local data (custom actions, proxy config, site lists, API keys) is wiped and defaults return</li><li>&quot;Export&quot; first if you might want it back; a bad config is one import away from restored</li></ol><h2 id="where-do-i-suggest-features-or-report-bugs" tabindex="-1">Where do I suggest features or report bugs? <a class="header-anchor" href="#where-do-i-suggest-features-or-report-bugs" aria-label="Permalink to &quot;Where do I suggest features or report bugs?&quot;">​</a></h2><p><strong>Steps</strong>: open a <a href="https://github.com/fedtop/DevGo/issues" target="_blank" rel="noreferrer">GitHub issue</a>. For bugs, include: browser and version, DevGo version (visible in settings or <code>chrome://extensions</code>), steps to reproduce, and a screenshot of the error — it speeds up diagnosis considerably.</p>',47)])])}const g=t(a,[["render",r]]);export{u as __pageData,g as default};
